import re
import subprocess
from typing import Annotated

from pydantic import BaseModel, Field, field_validator

# Allowlists: describe exactly what is valid instead of guessing what is bad
HOSTNAME = r"^[a-z0-9][a-z0-9-]{0,62}\.example\.com$"
INTERFACE = r"^(GigabitEthernet|TenGigabitEthernet)[1-9]/0/([1-9]|[1-4][0-9])$"
SAFE_TEXT = re.compile(r"[A-Za-z0-9 _.,:/()-]{1,64}")   # no newlines, no "!", no "|"


class AccessPortChange(BaseModel):
    device: Annotated[str, Field(pattern=HOSTNAME)]
    interface: Annotated[str, Field(pattern=INTERFACE)]
    vlan: Annotated[int, Field(ge=2, le=4094)]
    description: str

    @field_validator("vlan")
    @classmethod
    def not_reserved(cls, v: int) -> int:
        if 1002 <= v <= 1005:
            raise ValueError("VLANs 1002-1005 are reserved")
        return v

    @field_validator("description")
    @classmethod
    def safe_description(cls, v: str) -> str:
        if not SAFE_TEXT.fullmatch(v):
            raise ValueError("description contains characters that are not allowed")
        return v


def reachable(device: str) -> bool:
    # List form and no shell: a hostname can never become a second command
    result = subprocess.run(["ping", "-c", "2", device], capture_output=True, timeout=10)
    return result.returncode == 0

